import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { MicrophoneIcon } from '@heroicons/react/24/solid';

const VoiceRecordingPage: React.FC = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const navigate = useNavigate();

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(chunksRef.current, { type: 'audio/wav' });
        const file = new File([audioBlob], 'recorded-audio.wav', { type: 'audio/wav' });
        setAudioFile(file);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (error) {
      console.error('Error accessing microphone:', error);
      alert('Error accessing microphone. Please ensure you have granted microphone permissions.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type.startsWith('audio/')) {
        setAudioFile(file);
      } else {
        alert('Please upload an audio file (MP3 or WAV)');
      }
    }
  };

  const handleSubmit = async () => {
    if (!audioFile) {
      alert('Please record or upload an audio file first');
      return;
    }

    try {
      const formData = new FormData();
      formData.append('file', audioFile);
      formData.append('language', 'en');
      
      const response = await fetch('http://localhost:8000/api/voice/clone', {
        method: 'POST',
        body: formData,
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to clone voice');
      }
      
      const data = await response.json();
      console.log('Voice cloned successfully:', data);
      
      localStorage.setItem('voicePath', data.voice_path);
      navigate('/upload-document');
    } catch (error) {
      console.error('Error cloning voice:', error);
      alert(`Error cloning voice: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <div className="max-w-4xl mx-auto py-12 px-4">
        <h1 className="text-4xl font-bold text-center mb-12">Voice Recording</h1>
        
        <div className="bg-white rounded-lg shadow-sm p-8 mb-8">
          <h2 className="text-2xl font-semibold mb-6">Record Your Voice</h2>
          <div className="flex justify-center">
            <button
              onClick={isRecording ? stopRecording : startRecording}
              className="flex items-center px-6 py-3 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
            >
              <MicrophoneIcon className="h-6 w-6 mr-2" />
              {isRecording ? 'Stop Recording' : 'Start Recording'}
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-8">
          <h2 className="text-2xl font-semibold mb-6">Or Upload Audio File</h2>
          <div className="flex flex-col items-center">
            <button
              onClick={() => document.getElementById('audio-upload')?.click()}
              className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors mb-4"
            >
              Choose File
            </button>
            <input
              id="audio-upload"
              type="file"
              accept="audio/*"
              onChange={handleFileUpload}
              className="hidden"
            />
            {audioFile && (
              <div className="text-gray-600 mt-2">
                Selected file: {audioFile.name}
              </div>
            )}
          </div>
        </div>

        {audioFile && (
          <div className="mt-8 flex justify-center">
            <button
              onClick={handleSubmit}
              className="px-8 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
            >
              Continue to Document Upload
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default VoiceRecordingPage;
